package dev.gbppimentel.snapcompanion;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;
public class GameMemoryLinkTest {
 private JSONObject sample()throws Exception{return new JSONObject().put("token","session").put("pid",123).put("at",10000).put("status","ready").put("courseId",2).put("level",1).put("distance",12).put("length",100);}
 @Test public void acceptsCurrentSelectedLevelAndCourse()throws Exception{JSONObject r=GameMemoryLink.validate(sample(),"session","123",10500);assertEquals(2,r.getInt("courseId"));assertEquals(1,r.getInt("level"));}
 @Test public void rejectsOldSessionProcessStaleAndFuture()throws Exception{assertTrue(GameMemoryLink.validate(sample(),"old","123",10500).length()==0);assertTrue(GameMemoryLink.validate(sample(),"session","124",10500).length()==0);assertTrue(GameMemoryLink.validate(sample(),"session","123",11001).length()==0);assertTrue(GameMemoryLink.validate(sample(),"session","123",9999).length()==0);}
 @Test public void discoveryAndInvalidFieldsNeverBecomeCurrentCourse()throws Exception{for(String state:new String[]{"seeking","unsupported","ambiguous","unavailable"})assertTrue(GameMemoryLink.validate(sample().put("status",state),"session","123",10500).length()==0);assertTrue(GameMemoryLink.validate(sample().put("level",0),"session","123",10500).length()==0);assertTrue(GameMemoryLink.validate(sample().put("courseId",31),"session","123",10500).length()==0);assertTrue(GameMemoryLink.validate(sample().put("distance",101),"session","123",10500).length()==0);}
 @Test public void idleHasNoInventedCourseRequirement()throws Exception{assertEquals("idle",GameMemoryLink.validate(new JSONObject().put("token","session").put("pid",123).put("at",10000).put("status","idle"),"session","123",10500).getString("status"));}
 @Test public void mapProjectionKeepsGameFieldsAndDropsPrivateMetadata()throws Exception{JSONObject row=sample().put("course","park-night").put("phaseRva",0x630240).put("world",new org.json.JSONArray("[1,2,3]")).put("routePoints",new org.json.JSONArray("[[1,2,3],[4,5,6]]")).put("routeKey","2:100");JSONObject ui=GameMemoryLink.uiSnapshot(row);assertEquals("paused",ui.getString("phase"));assertEquals(10000,ui.getLong("sampleAt"));assertEquals(2,ui.getJSONArray("routePoints").length());assertFalse(ui.has("pid"));assertFalse(ui.has("token"));assertFalse(ui.has("phaseRva"));}
 @Test public void malformedMapGeometryIsWithheldWithoutDiscardingCourse()throws Exception{JSONObject ui=GameMemoryLink.uiSnapshot(sample().put("course","park-night").put("world",new org.json.JSONArray("[1,2]")).put("routePoints",new org.json.JSONArray("[[1,2,3],[4,5]]")));assertEquals("park-night",ui.getString("course"));assertFalse(ui.has("world"));assertFalse(ui.has("routePoints"));}
 @Test public void toolAvailabilityRequiresLiveGameplayAndDropsUnknownFeedback()throws Exception{JSONObject row=sample().put("inputAvailable",true).put("phaseRva",0x62e180).put("lastAction",new JSONObject().put("action","shell").put("at",10000));JSONObject ui=GameMemoryLink.uiSnapshot(row);assertTrue(ui.getBoolean("tools"));assertFalse(ui.has("lastAction"));assertFalse(GameMemoryLink.uiSnapshot(row.put("phaseRva",0x630240)).getBoolean("tools"));assertFalse(GameMemoryLink.uiSnapshot(row.put("phaseRva",0x62e180).put("status","idle")).getBoolean("tools"));}
 private JSONObject camera()throws Exception{return new JSONObject().put("forward",new org.json.JSONArray("[0,0,-1]")).put("up",new org.json.JSONArray("[0,1,0]")).put("fovY",Math.PI/5).put("aspect",16.0/9);}
 @Test public void cameraProjectionWhitelistsOnlyValidatedViewingFields()throws Exception{JSONObject row=sample().put("phaseRva",0x62e180).put("camera",camera().put("address","private").put("eye",new org.json.JSONArray("[1,2,3]")));JSONObject c=GameMemoryLink.uiSnapshot(row).getJSONObject("camera");assertEquals(4,c.length());assertFalse(c.has("address"));assertFalse(c.has("eye"));assertTrue(GameMemoryLink.uiSnapshot(row.put("phaseRva",0x630240)).has("camera"));assertFalse(GameMemoryLink.uiSnapshot(row.put("phaseRva",0)).has("camera"));assertFalse(GameMemoryLink.uiSnapshot(row.put("phaseRva",0x62e180).put("status","idle")).has("camera"));}
 @Test public void malformedCameraNeverBecomesAViewDirection()throws Exception{assertNull(GameMemoryLink.cameraSnapshot(camera().put("fovY",0)));assertNull(GameMemoryLink.cameraSnapshot(camera().put("aspect",9)));assertNull(GameMemoryLink.cameraSnapshot(camera().put("forward",new org.json.JSONArray("[0,0,0]"))));assertNull(GameMemoryLink.cameraSnapshot(camera().put("up",new org.json.JSONArray("[0,0,-1]"))));assertNull(GameMemoryLink.cameraSnapshot(camera().put("forward",new org.json.JSONArray("[0,1]"))));}
}
